import {accountsEnabled,refreshAccountHeader} from './account-header.js';
import {menu} from './galleteria-data.js';
const $=s=>document.querySelector(s), asset='/assets/galleteria/', ig='https://www.instagram.com/lagalleteriamx/', source='https://wanderlog.com/place/details/4370460', press='https://elpais.com/mexico/opinion/2024-12-13/lagalleteria-la-mini-fabrica-de-galletas-para-saciar-tu-diente-dulce.html', maps='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('lagalletería Fernando Montes de Oca 28 Condesa Ciudad de México');
let lang='es', category='all', query='';try{lang=sessionStorage.getItem('lavita-language')==='en'?'en':'es';}catch{}
const t=(es,en)=>lang==='es'?es:en, norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const photos=[['mostrador-ia.jpg','Mostrador · versión retocada con IA','Counter · AI-retouched version'],['cocina-ia.jpg','En la cocina · versión retocada con IA','In the kitchen · AI-retouched version'],['6-Photo-6.jpg','Fachada · fotografía original','Exterior · original photograph'],['1-Photo-1.jpg','Interior · fotografía original','Interior · original photograph'],['3-Photo-3.jpg','Mostrador · fotografía original','Counter · original photograph'],['2-Photo-2.jpg','Cocina · fotografía original','Kitchen · original photograph'],['5-Photo-5.jpg','Menú fotografiado · fuente de los precios','Photographed menu · price source'],['4-Photo-4.jpg','Horario fotografiado','Photographed opening hours']];
const link=(url,label,cls='')=>`<a class="${cls}" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const photo=(i,cls='')=>`<button class="photo ${cls}" data-photo="${i}" aria-label="${t('Ampliar','Enlarge')}: ${t(photos[i][1],photos[i][2])}"><img src="${asset+photos[i][0]}" alt="${t(photos[i][1],photos[i][2])}" ${i>2?'loading="lazy"':''}><span>${t(photos[i][1],photos[i][2])}</span></button>`;
function render(){document.documentElement.lang=lang;$('#shop-language').value=lang;document.querySelectorAll('[data-es]').forEach(e=>e.textContent=e.dataset[lang]);
$('#shop-content').innerHTML=`<div class="crumb"><a href="/">${t('Explorar','Explore')}</a> / ${t('Café y postres','Coffee & sweets')} / Condesa</div><div class="shop-title"><div><p class="shop-kicker">CONDESA · ${t('GALLETAS & CAFÉ','COOKIES & COFFEE')}</p><h1>La Galletería<span>lagalletería</span></h1><p class="shop-sub">${t('Una pausa dulce, hecha en el barrio.','A sweet little break, made in the neighborhood.')}</p><div class="shop-meta"><a href="#opiniones">★ 4.8 <span>(118 ${t('reseñas','reviews')}) · Google / Wanderlog</span></a><span>·</span><span>${t('Galletas desde','Cookies from')} $60 MXN</span><span>·</span><span id="open-status"></span></div></div><div class="title-actions"><button id="save-shop">♡ ${t('Guardar','Save')}</button><button id="share-shop">↗ ${t('Compartir','Share')}</button></div></div><section id="fotos" class="shop-gallery" aria-label="${t('Galería','Gallery')}">${photo(0,'shop-hero')}${photo(1)}${photo(2)}</section><div class="gallery-foot"><small>${t('2 versiones retocadas con IA · Originales disponibles en la galería.','2 AI-retouched versions · Originals available in the gallery.')}</small><button data-photo="3">▦ ${t('Ver las 8 fotos','View all 8 photos')}</button></div><nav class="shop-tabs" aria-label="${t('Secciones de la tienda','Shop sections')}"><a href="#menu">${t('Menú','Menu')}</a><a href="#especialidad">${t('Lo especial','Highlights')}</a><a href="#opiniones">${t('Opiniones','Reviews')}</a><a href="#visita">${t('Ubicación y horario','Location & hours')}</a></nav><div class="shop-layout"><div><section id="especialidad" class="shop-section"><p class="shop-kicker">${t('EL ANTOJO','YOUR NEXT TREAT')}</p><h2>${t('Pequeña tienda. Mucha personalidad.','Small shop. Big personality.')}</h2><p>${t('Galletas, whoopies y una carta de café, matcha y bebidas frías. Un mostrador lavanda, vitrinas de galletas y la cocina a la vista: así se vive esta parada en Condesa.','Cookies, whoopie pies, coffee, matcha and cold drinks. A lavender counter, cookie displays and an open kitchen set the scene for this Condesa stop.')}</p><div class="strengths"><span>◉ ${t('Galletas desde $60','Cookies from $60')}</span><span>◉ ${t('Café y matcha','Coffee & matcha')}</span><span>◉ ${t('Cocina a la vista','Open kitchen')}</span></div><div class="special-note"><b>${t('Una especialidad con historia','A signature with a story')}</b><p>${t('Tocino chocochip: una combinación dulce y salada destacada por El País en 2024. Joaquín Fernández y Juan Carlos Malagón están detrás del proyecto. Pregunta por los sabores disponibles hoy.','Bacon chocolate chip: a sweet-and-savory combination highlighted by El País in 2024. Joaquín Fernández and Juan Carlos Malagón are behind the project. Ask which flavors are available today.')}</p>${link(press,t('Leer la reseña de El País · 13 dic 2024','Read El País · Dec 13, 2024'))}</div></section><section id="menu" class="shop-section"><div class="section-head"><h2>${t('El menú','The menu')}</h2><button data-photo="6">${t('Ver carta original','View original menu')} ↗</button></div><p class="menu-note">${t('Precios en MXN, transcritos del menú fotografiado que nos compartieron. Sujetos a cambios en el local.','Prices in MXN, transcribed from the supplied menu photograph. Subject to change at the shop.')}</p><label class="menu-search">⌕ <input id="menu-query" type="search" aria-label="${t('Buscar en el menú','Search the menu')}" placeholder="${t('Busca matcha, café, galletas…','Search matcha, coffee, cookies…')}"></label><div class="menu-filters" aria-label="${t('Categorías del menú','Menu categories')}">${[['all','Todo','All'],['cookies','Galletas','Cookies'],['hot','Calientes','Hot drinks'],['cold','Frías','Cold drinks'],['extras','Extras','Extras']].map(([id,es,en])=>`<button data-menu="${id}" aria-pressed="${category===id}">${t(es,en)}</button>`).join('')}</div><div id="menu-items"></div><p class="menu-note">${t('Sabores según disponibilidad. Para ingredientes y alérgenos, consulta directamente al equipo antes de pedir.','Flavors depend on availability. Ask the team about ingredients and allergens before ordering.')}</p></section><section id="opiniones" class="shop-section"><div class="section-head"><h2>${t('Lo que cuentan','What visitors say')}</h2>${link(maps,'Google Maps')}</div><div class="rating-row"><strong>4.8<span>/5</span></strong><div><b>★★★★★</b><p>118 ${t('reseñas de Google recogidas por Wanderlog','Google reviews shown on Wanderlog')}</p></div></div><p class="menu-note">${t('Referencia consultada el 17 nov 2026; no sincronizada en vivo. Selección de opiniones, no el total.','Reference checked Nov 17, 2026; not synced live. Selected reviews, not the full set.')}</p><div class="review-grid">${[['Nicole P','20 dic 2025','Dec 20, 2025','Destaca la textura, los sabores y el trato de los dueños.','Highlights the texture, flavors and owners’ friendliness.'],['M J','29 oct 2023','Oct 29, 2023','Recomienda churro Nutella y la explicación de sabores en inglés.','Recommends churro Nutella and English explanations of the flavors.'],['Ian D','7 abr 2024','Apr 7, 2024','Valora la variedad de galletas y el ambiente acogedor.','Appreciates the cookie variety and welcoming atmosphere.']].map(r=>`<article><b>${r[0]}</b><span>★★★★★ · ${t(r[1],r[2])}</span><p>${t(r[3],r[4])}</p><small>${t('Resumen de reseña · Google vía Wanderlog','Review summary · Google via Wanderlog')}</small></article>`).join('')}</div>${link(source,t('Consultar opiniones y calificación en la fuente','View reviews and rating at the source'))}</section><section class="shop-section"><div class="section-head"><h2>${t('Así se ve por dentro','A look inside')}</h2></div><div class="original-grid">${photo(3)}${photo(4)}${photo(5)}</div></section></div><aside id="visita"><div class="visit-card"><p class="shop-kicker">${t('NOS VEMOS EN CONDESA','SEE YOU IN CONDESA')}</p><h2>${t('Haz una pausa.','Take a break.')}</h2><p><b>Fernando Montes de Oca 28</b><br>Local B · Colonia Condesa<br>Cuauhtémoc, CDMX · 06140</p>${link(maps,t('Cómo llegar','Get directions'),'visit-primary')}<a class="visit-secondary" href="#menu">${t('Ver menú y precios','View menu & prices')}</a><div class="visit-hours"><b>${t('Martes a domingo','Tuesday–Sunday')}</b><strong>12:00–19:00</strong><span>${t('Lunes cerrado','Closed Mondays')}</span></div><small>${t('Horario del letrero fotografiado. Confirma cambios y días festivos en Instagram.','Hours from the photographed sign. Confirm changes and holidays on Instagram.')}</small>${link(ig,'@lagalleteriamx','instagram-link')}<div class="budget"><span>${t('Galleta + americano','Cookie + Americano')}</span><b>$110 MXN</b><small>${t('Suma del menú, no es una promoción.','Menu total, not a special offer.')}</small></div></div></aside></div><details class="shop-sources"><summary>${t('Fuentes y fotografías','Sources & photographs')}</summary><p>${t('Menú y horario: fotografías aportadas para esta ficha. Consulta editorial: 17 de noviembre de 2026. Los retoques IA son versiones ilustrativas basadas en esas fotos; puedes consultar los originales.','Menu and hours: photographs supplied for this listing. Editorial check: November 17, 2026. AI retouches are illustrative versions based on these photos; originals are available.')}</p><p>${t('Wanderlog indica cierre a las 20:00 los sábados; se prioriza el letrero del local (19:00). Calificación y reseñas son referencias externas, no evaluaciones de La Vita.','Wanderlog lists Saturday closing at 20:00; the shop sign (19:00) takes precedence here. Ratings and reviews are external references, not La Vita reviews.')}</p>${link(source,'Wanderlog')} · ${link(press,'El País')} · ${link(ig,'Instagram')}</details><div class="mobile-action"><span>${t('Galletas desde','Cookies from')} <b>$60</b></span><a href="#menu">${t('Menú','Menu')}</a>${link(maps,t('Cómo llegar','Directions'))}</div>`;
$('#menu-query').value=query;$('#menu-query').oninput=e=>{query=e.target.value;renderMenu();};renderMenu();updateOpen();updateSave();
$('#save-shop').onclick=()=>{let saved=false;try{saved=sessionStorage.getItem('lavita-galleteria-saved')==='1';sessionStorage.setItem('lavita-galleteria-saved',saved?'0':'1');}catch{notify(t('No se pudo guardar en este navegador.','Could not save in this browser.'));return;}updateSave();};
$('#share-shop').onclick=async()=>{const url='https://roma-condesa.app/lugares/la-galleteria';try{await navigator.clipboard.writeText(url);notify(t('Enlace copiado.','Link copied.'));}catch{notify(url);}};
}
function renderMenu(){const rows=menu.filter(r=>(category==='all'||r[0]===category)&&norm(r[1]+' '+r[2]).includes(norm(query)));$('#menu-items').innerHTML=rows.length?rows.map(r=>`<article class="menu-item"><div><h3>${t(r[1],r[2])}</h3><small>${r[4]||t(r[0]==='extras'?'Adicional':'Por pieza',r[0]==='extras'?'Add-on':'Per piece')} ${category==='all'&&['hot','cold'].includes(r[0])?'· '+t(r[0]==='hot'?'Caliente':'Fría',r[0]==='hot'?'Hot':'Cold'):''}</small></div><strong>${r[0]==='extras'?'+':''}$${r[3]}</strong></article>`).join(''):`<p>${t('No encontramos ese producto.','No matching items.')}</p>`;}
function updateOpen(){const e=$('#open-status');if(!e)return;const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Mexico_City',weekday:'short',hour:'numeric',hourCycle:'h23'}).formatToParts(new Date()), day=parts.find(p=>p.type==='weekday')?.value,hour=Number(parts.find(p=>p.type==='hour')?.value);e.textContent=day!=='Mon'&&hour>=12&&hour<19?t('Abierto según horario','Open per listed hours'):t('Cerrado según horario','Closed per listed hours');}
function updateSave(){let s=false;try{s=sessionStorage.getItem('lavita-galleteria-saved')==='1';}catch{}$('#save-shop').textContent=s?t('♥ Guardado','♥ Saved'):t('♡ Guardar','♡ Save');$('#save-shop').setAttribute('aria-pressed',s);}
function notify(msg){$('#shop-status').textContent=msg;$('#shop-status').classList.add('visible');setTimeout(()=>$('#shop-status').classList.remove('visible'),5000);}
let photoIndex=0,previousFocus;
function showPhoto(i){photoIndex=(i+photos.length)%photos.length;$('#large-photo').src=asset+photos[photoIndex][0];$('#large-photo').alt=t(photos[photoIndex][1],photos[photoIndex][2]);$('#photo-caption').textContent=`${photoIndex+1} / ${photos.length} · ${t(photos[photoIndex][1],photos[photoIndex][2])}`;if(!$('#photo-dialog').open){previousFocus=document.activeElement;$('#photo-dialog').showModal();}}
$('#photo-dialog').insertAdjacentHTML('beforeend','<div class="photo-controls"><button id="prev-photo" aria-label="Anterior / Previous">←</button><button id="next-photo" aria-label="Siguiente / Next">→</button></div>');
$('#close-photo').onclick=()=>$('#photo-dialog').close();$('#photo-dialog').addEventListener('close',()=>previousFocus?.focus());$('#prev-photo').onclick=()=>showPhoto(photoIndex-1);$('#next-photo').onclick=()=>showPhoto(photoIndex+1);$('#photo-dialog').onkeydown=e=>{if(e.key==='ArrowRight')showPhoto(photoIndex+1);if(e.key==='ArrowLeft')showPhoto(photoIndex-1);};
$('#shop-content').onclick=e=>{const p=e.target.closest('[data-photo]');if(p)showPhoto(+p.dataset.photo);const b=e.target.closest('[data-menu]');if(b){category=b.dataset.menu;document.querySelectorAll('[data-menu]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderMenu();}};
$('#shop-language').onchange=e=>{lang=e.target.value;try{sessionStorage.setItem('lavita-language',lang);}catch{}render();};
if(accountsEnabled){refreshAccountHeader();}else{try{const u=JSON.parse(sessionStorage.getItem('lavita-community-demo'));if(u&&typeof u.name==='string'&&Number.isFinite(u.points))$('#shop-profile').textContent=u.name+' · '+u.points.toLocaleString()+' pts · Demo';else $('#shop-profile').textContent+=' · Demo';}catch{}}
render();setInterval(updateOpen,60000);
